import { describe, expect, it } from 'vitest';
import { worktreeYmlErrors } from './edit.js';
import { containerEntryName, withContainerPreview } from './container-preview.js';
import { parseWorktreeYml } from './load.js';

const REF = { file: 'compose.yaml', service: 'web', port: 8080 };
const WIZARD_V1 = [
  '# Generated by the Emberline project wizard. Runs read the approved copy of this file.',
  'version: 1',
  'setup:',
  '  - "[ ! -f package.json ] || pnpm install"',
  'services:',
  '  - name: web',
  '    command: "pnpm dev --port $PORT --host 0.0.0.0"',
  '    preview: true',
  'checks:',
  '  build: "pnpm build"',
  '',
].join('\n');

describe('withContainerPreview', () => {
  it('keeps a comment under an empty services key', () => {
    expect(withContainerPreview('version: 1\nservices:\n  # none yet\n', REF)).toContain('# none yet');
  });

  it('keeps setup, checks and services, demotes the old preview and adds the container entry', () => {
    const out = withContainerPreview(WIZARD_V1, REF);
    const parsed = parseWorktreeYml(out);
    expect(parsed.ok, out).toBe(true);
    if (!parsed.ok) return;
    expect(parsed.config.version).toBe(2);
    expect(parsed.config.setup).toEqual(['[ ! -f package.json ] || pnpm install']);
    expect(parsed.config.checks).toEqual({ build: 'pnpm build' });
    expect(parsed.config.services).toEqual([
      { name: 'web', command: 'pnpm dev --port $PORT --host 0.0.0.0', preview: false },
      { name: 'container', compose: { file: 'compose.yaml', service: 'web', port: 8080 }, preview: true },
    ]);
    // Comments and unrelated lines come through as they were.
    expect(out.startsWith('# Generated by the Emberline project wizard.')).toBe(true);
    expect(out).toContain('  - "[ ! -f package.json ] || pnpm install"\n');
    expect(out).toContain('  build: "pnpm build"\n');
  });

  it('takes container-2 when container is taken', () => {
    const yml = 'version: 1\nservices:\n  - name: container\n    command: "x"\n    preview: true\n';
    const parsed = parseWorktreeYml(withContainerPreview(yml, REF));
    expect(parsed.ok && parsed.config.services.map((s) => s.name)).toEqual(['container', 'container-2']);
    expect(containerEntryName(new Set(['container', 'container-2']))).toBe('container-3');
  });

  it('writes a new file without an approval, and turns a flow list into a block list', () => {
    for (const approved of [null, '', 'version: 1\nservices: []\n']) {
      const out = withContainerPreview(approved, REF);
      expect(worktreeYmlErrors(out), out).toEqual([]);
      expect(out).toContain('  - name: container\n');
    }
  });

  it('keeps a file written with unindented lists as it was (Review Focus 2)', () => {
    const yml = 'version: 1\nsetup:\n- "pnpm i"\nservices:\n- name: web\n  command: "x"\n  preview: true\n';
    const out = withContainerPreview(yml, REF);
    expect(worktreeYmlErrors(out), out).toEqual([]);
    expect(out).toContain(
      'setup:\n- "pnpm i"\nservices:\n- name: web\n  command: "x"\n  preview: false\n- name: container\n',
    );
  });

  it('does not fold long commands (Review Focus 2)', () => {
    const long = `echo ${'x'.repeat(150)}`;
    const out = withContainerPreview(`version: 1\nsetup:\n  - ${JSON.stringify(long)}\n`, REF);
    expect(out).toContain(`  - ${JSON.stringify(long)}\n`);
  });

  it('a 21st service makes the file invalid with the schema words', () => {
    const services = Array.from({ length: 20 }, (_, i) => `  - name: s${i}\n    command: "true"\n`).join('');
    expect(
      worktreeYmlErrors(withContainerPreview(`version: 1\nservices:\n${services}`, REF)).join(' '),
    ).toMatch(/services/);
  });

  it('keeps a short flow list as written', () => {
    const out = withContainerPreview('version: 1\nsetup: [npm ci]\n', REF);
    expect(out).toContain('setup: [npm ci]\n');
  });

  it('keeps CRLF line endings', () => {
    const out = withContainerPreview(WIZARD_V1.replace(/\n/g, '\r\n'), REF);
    expect(out.replace(/\r\n/g, '')).not.toMatch(/[\r\n]/);
    expect(out.match(/\n/g)?.length).toBe(out.match(/\r\n/g)?.length);
    expect(worktreeYmlErrors(out)).toEqual([]);
  });
});
